const normalizedStatus=s=>({arrived:'checked_in',waiting:'booked',in_treatment:'checked_in',no_show:'cancelled'}[s]||s);
function localDateTimeValue(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const p=x=>String(x).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
