// v2.0 diagnostic screen. NEVER merges PostgreSQL pilot IDs with the SQLite app.
function PgPilot({api,eid}){
 const receiptAttempt=useRef({fingerprint:null,key:null});
 const [operation,setOperation]=useState('registration');
 const [form,setForm]=useState({name:'Synthetic Test Patient',phone:'',registration_id:'',patient_id:'',
   visit_id:'',planned_by:'',description:'Dental consultation',tooth_number:'16',
   treatment_id:'',amount:'500.00',invoice_id:'',payment_mode:'CASH'});
 const [result,setResult]=useState(null),[message,setMessage]=useState('');
 const set=(field,value)=>setForm(x=>({...x,[field]:value}));
 useEffect(()=>{receiptAttempt.current={fingerprint:null,key:null};setResult(null);setMessage('');setForm(x=>({...x,registration_id:'',patient_id:'',visit_id:'',treatment_id:'',invoice_id:''}))},[eid]);
 const go=async(e)=>{
  e.preventDefault();setMessage('');setResult(null);
  const n=k=>Number(form[k]);const url=`/entities/${eid}/pg-pilot`;
  try{
   let path='',body=null,method='POST';
   if(operation==='registration'){path='/registrations';body={name:form.name,phone:form.phone};}
   if(operation==='checkin'){path='/check-in';body={registration_id:n('registration_id')};}
   if(operation==='visit'){path='/visits';body={patient_id:n('patient_id'),chief_complaint:'Synthetic test visit'};}
   if(operation==='treatment'){path='/treatments';body={patient_id:n('patient_id'),visit_id:n('visit_id'),planned_by:n('planned_by'),description:form.description,tooth_number:n('tooth_number')};}
   if(operation==='invoice'){path='/invoices';body={patient_id:n('patient_id'),items:[{treatment_id:n('treatment_id'),amount:form.amount}]};}
   if(operation==='receipt'){
    path='/receipts';body={patient_id:n('patient_id'),amount:form.amount,payment_mode:form.payment_mode,allocations:[{invoice_id:n('invoice_id'),amount:form.amount}]};
    const fingerprint=JSON.stringify({eid,...body});
    if(receiptAttempt.current.fingerprint!==fingerprint){receiptAttempt.current={fingerprint,key:window.crypto.randomUUID()};}
    body.idempotency_key=receiptAttempt.current.key;
   }
   if(operation==='ledger'){path=`/patients/${n('patient_id')}/ledger`;method='GET';}
   const response=await api(url+path,body,method);
   setResult(response);
   if(response.temp_id)set('registration_id',String(response.id));
   if(response.patient)set('patient_id',String(response.patient.id));
   if(response.visit_number)set('visit_id',String(response.id));
   if(response.number && operation==='treatment')set('treatment_id',String(response.id));
   if(response.invoice_number)set('invoice_id',String(response.id));
  }catch(error){setMessage(error.message)}
 };
 const inputs={
  registration:[['name','Patient name'],['phone','Phone (synthetic only)']],
  checkin:[['registration_id','Pilot registration ID']],
  visit:[['patient_id','Pilot patient ID']],
  treatment:[['patient_id','Pilot patient ID'],['visit_id','Pilot visit ID'],['planned_by','Pilot doctor ID'],['description','Procedure'],['tooth_number','FDI tooth number']],
  invoice:[['patient_id','Pilot patient ID'],['treatment_id','Pilot treatment ID'],['amount','Amount (₹)']],
  receipt:[['patient_id','Pilot patient ID'],['invoice_id','Pilot invoice ID'],['amount','Amount (₹)'],['payment_mode','Payment mode']],
  ledger:[['patient_id','Pilot patient ID']]
 };
 return <div className="two-col"><Card><Heading title="PostgreSQL synthetic-data pilot"/>
  <p className="helper">Restricted administrator diagnostics, disabled by default. IDs on this screen belong only to the PostgreSQL pilot. They must never be used in the operational SQLite patient, calendar or billing screens.</p>
  <form className="form-grid" onSubmit={go}>
   <Field label="Pilot action"><select value={operation} onChange={e=>{setOperation(e.target.value);setMessage('');setResult(null)}}>
    {Object.keys(inputs).map(x=><option key={x} value={x}>{({registration:'Temporary registration',checkin:'First check-in / UHID',visit:'Create visit',treatment:'Create treatment',invoice:'Create invoice',receipt:'Post receipt',ledger:'View patient ledger'})[x]}</option>)}
   </select></Field>
   {inputs[operation].map(([field,label])=><Field key={field} label={label}><input required value={form[field]||''} onChange={e=>set(field,e.target.value)}/></Field>)}
   <button className="primary" type="submit">Run synthetic pilot action</button>
  </form></Card><Card><Heading title="Diagnostic result"/>
  {message&&<div role="alert" className="alert danger">{message}</div>}
  {result?<pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere',fontSize:12}}>{JSON.stringify(result,null,2)}</pre>:<Empty text="No diagnostic action run in this session."/>}
  <p className="helper">No live clinical data. PostgreSQL must be provisioned, isolated and independently validated before enabling these endpoints.</p>
  </Card></div>
}
